<section class="container section"><div class="page-head"><div><p class="overline">KẾT QUẢ TUYỂN SINH / QUẢN LÝ CÔNG BỐ</p><h1>Phê duyệt và công bố</h1><p class="muted">Kết quả chỉ hiện cho thí sinh sau khi toàn kỳ được công bố; trường THPT được xem danh sách đã duyệt.</p></div></div><div class="card table-wrap"><table><thead><tr><th>Mã kỳ</th><th>Tên kỳ</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach($exams as $ex):?><tr><td><?=e($ex['code'])?></td><td><?=e($ex['name'])?></td><td><?=e($ex['status'])?></td><td><form method="post" action="<?=e(url('quan-tri/cong-bo'))?>" class="gradeform" onsubmit="return confirm('Bạn có chắc muốn thay đổi trạng thái kỳ tuyển sinh?')"><?=field('publish')?><input type="hidden" name="exam_id" value="<?=$ex['id']?>"><input type="hidden" name="action" value="<?=$ex['status']==='approved'?'publish':'approve'?>"><input name="basis" required placeholder="Căn cứ phê duyệt/công bố" minlength="5"><button <?=$ex['status']==='published'?'disabled':''?> class="btn btn-main btn-small"><?=$ex['status']==='approved'?'Công bố':'Phê duyệt'?></button></form></td></tr><?php endforeach;?></tbody></table></div></section>
